-- El gerente de prueba (02_siembra_usuarios.sql) queda asignado a la sucursal Palermo
UPDATE usuarios SET id_sucursal = 1
WHERE email = 'gerente@outlet.com' AND id_sucursal IS NULL;

-- Secuencias de los serial

SELECT setval(pg_get_serial_sequence('sucursales', 'id_sucursal'), COALESCE((SELECT MAX(id_sucursal) FROM sucursales), 1));
SELECT setval(pg_get_serial_sequence('marcas', 'id_marca'), COALESCE((SELECT MAX(id_marca) FROM marcas), 1));
SELECT setval(pg_get_serial_sequence('categorias', 'id_categoria'), COALESCE((SELECT MAX(id_categoria) FROM categorias), 1));
SELECT setval(pg_get_serial_sequence('productos', 'id_producto'), COALESCE((SELECT MAX(id_producto) FROM productos), 1));
SELECT setval(pg_get_serial_sequence('stock', 'id_stock'), COALESCE((SELECT MAX(id_stock) FROM stock), 1));
SELECT setval(pg_get_serial_sequence('clientes', 'id_cliente'), COALESCE((SELECT MAX(id_cliente) FROM clientes), 1));
SELECT setval(pg_get_serial_sequence('objetivos_venta', 'id_objetivo'), COALESCE((SELECT MAX(id_objetivo) FROM objetivos_venta), 1));
SELECT setval(pg_get_serial_sequence('ventas', 'id_venta'), COALESCE((SELECT MAX(id_venta) FROM ventas), 1));
SELECT setval(pg_get_serial_sequence('detalle_ventas', 'id_detalle'), COALESCE((SELECT MAX(id_detalle) FROM detalle_ventas), 1));
